#include <opencv2/opencv.hpp>
#include <iostream>

using namespace cv;
using namespace std;

int main() {
    // 读取图像
    Mat image = imread("test.jpg");

    // 检查图像是否成功加载
    if (image.empty()) {
        cout << "错误：无法加载图像，请检查路径是否正确。" << endl;
        return -1;
    }

    // 显示图像
    namedWindow("Display Image", WINDOW_AUTOSIZE);
    imshow("Display Image", image);

    // 等待按键
    waitKey(0);

    // 关闭窗口
    destroyAllWindows();

    return 0;
}

#include <opencv2/opencv.hpp>

int main() {
    cv::Mat src = cv::imread("image.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat dst, dst_norm;

    // Harris角点检测
    cv::cornerHarris(src, dst, 2, 3, 0.04);

    // 归一化并显示结果
    cv::normalize(dst, dst_norm, 0, 255, cv::NORM_MINMAX, CV_32FC1, cv::Mat());
    cv::imshow("Harris Corners", dst_norm);
    cv::waitKey(0);

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

using namespace cv;
using namespace std;

int main() {
    Mat image = imread("test.jpg");
    if (image.empty()) {
        cout << "错误：无法加载图像，请检查路径是否正确。" << endl;
        return -1;
    }

    // 均值滤波
    Mat blurredImage;
    blur(image, blurredImage, Size(5, 5)); // 5x5 的核

    imshow("Original Image", image);
    imshow("Blurred Image", blurredImage);
    waitKey(0);
    destroyAllWindows();

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
    // 生成一些随机数据
    cv::Mat data(100, 2, CV_32F);
    cv::randu(data, cv::Scalar(0, 0), cv::Scalar(100, 100));

    // 设置K值和迭代条件
    int K = 3;
    cv::Mat labels, centers;
    cv::kmeans(data, K, labels, cv::TermCriteria(cv::TermCriteria::EPS + cv::TermCriteria::MAX_ITER, 10, 1.0), 3, cv::KMEANS_PP_CENTERS, centers);

    // 输出结果
    std::cout << "Labels: " << labels << std::endl;
    std::cout << "Centers: " << centers << std::endl;

    return 0;
}

#include <opencv2/opencv.hpp>
#include <opencv2/core/ocl.hpp>

int main() {
    cv::ocl::setUseOpenCL(true); // 启用 OpenCL 加速
    cv::UMat src, dst;
    cv::imread("image.jpg").copyTo(src);
    cv::GaussianBlur(src, dst, cv::Size(5, 5), 0);
    cv::imshow("Blurred Image", dst);
    cv::waitKey(0);
    return 0;
}

